// Parse incoming webhook payload
const body = $input.first().json.body || $input.first().json;

const domain = body.domain;
const managerEmail = body.manager_email || '';
const folderUrl = body.folder_url || '';

// Decode internal_all.xlsx from base64
const internalAll = body.internal_all;
if (!internalAll || !internalAll.data) {
  throw new Error('internal_all.xlsx file is required');
}

// Store binary data for XLSX parsing
const binaryData = Buffer.from(internalAll.data, 'base64');

// Optional files
const imagesAlt = body.images_alt || [];
const backlinks = body.backlinks || null;

return [{
  json: {
    domain,
    managerEmail,
    folderUrl,
    hasImagesAlt: imagesAlt.length > 0,
    hasBacklinks: !!backlinks
  },
  binary: {
    internal_all: {
      data: internalAll.data,
      mimeType: internalAll.mimeType || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName: internalAll.name || 'internal_all.xlsx'
    }
  }
}];

// Process all rows from Spreadsheet File node
const items = $input.all();
const domain = $('Parse Input').first().json.domain;

// Each item is a row from the XLSX
const all_rows = items.map(item => item.json).filter(r => r['Address']);
const headers = Object.keys(all_rows[0] || {});

// Pre-filter datasets for each agent
const pages_html = all_rows.filter(r => (r['Content Type'] || '').includes('text/html'));
const pages_200 = pages_html.filter(r => String(r['Status Code'] || '') === '200');
const pages_indexable = pages_200.filter(r => (r['Indexability'] || '') === 'Indexable');

// Canonicals: pages where canonical differs from URL
const pages_canonical = pages_html.filter(r =>
  r['Canonical Link Element 1'] &&
  r['Canonical Link Element 1'] !== r['Address']
);

// H1 problems
const pages_multi_h1 = pages_html.filter(r => (r['H1-2'] || '').trim());
const pages_missing_h1 = pages_indexable.filter(r => !(r['H1-1'] || '').trim());

// Status codes
const pages_301 = all_rows.filter(r => String(r['Status Code'] || '') === '301');
const pages_404 = all_rows.filter(r => String(r['Status Code'] || '') === '404');

// Tags
const pages_tags = pages_indexable.filter(r => (r['Address'] || '').includes('/tag/'));

// EN/UK split
const pages_en = pages_indexable.filter(r => !(r['Address'] || '').includes('/uk/'));
const pages_uk = pages_indexable.filter(r => (r['Address'] || '').includes('/uk/'));

// Meta issues: empty/short title or description
const pages_meta_issues = pages_indexable.filter(r => {
  const titleLen = parseInt(r['Title 1 Length'] || '0');
  const descLen = parseInt(r['Meta Description 1 Length'] || '0');
  return !r['Title 1'] || titleLen < 30 || titleLen > 60 ||
         !r['Meta Description 1'] || descLen < 70 || descLen > 160;
});

// No limit — pass all filtered data to agents
return [{
  json: {
    domain,
    total_pages: all_rows.length,
    total_html: pages_html.length,
    total_indexable: pages_indexable.length,
    headers,
    pages_canonical,
    pages_canonical_count: pages_canonical.length,
    pages_indexable,
    pages_indexable_count: pages_indexable.length,
    pages_multi_h1,
    pages_multi_h1_count: pages_multi_h1.length,
    pages_missing_h1,
    pages_missing_h1_count: pages_missing_h1.length,
    pages_301,
    pages_301_count: pages_301.length,
    pages_404,
    pages_404_count: pages_404.length,
    pages_tags,
    pages_tags_count: pages_tags.length,
    pages_en,
    pages_uk,
    pages_meta_issues,
    pages_meta_issues_count: pages_meta_issues.length
  }
}];

// Agent 1: Canonicals + Structure
const data = $('Parse XLSX').first().json;

const canonicals = data.pages_canonical.map(p => ({
  url: p['Address'] || '',
  canonical: p['Canonical Link Element 1'] || '',
  correct_canonical: p['Address'] || ''
}));

// Structure: match EN/UK pairs
const enPages = data.pages_en || [];
const ukPages = data.pages_uk || [];

const structure = [];
for (const en of enPages) {
  const enUrl = en['Address'] || '';
  const title = en['Title 1'] || en['H1-1'] || '';
  // Expected UK URL: replace domain root with /uk/
  const ukUrl = enUrl.replace(`https://${data.domain}/`, `https://${data.domain}/uk/`);
  const ukMatch = ukPages.find(uk => (uk['Address'] || '') === ukUrl);
  structure.push({
    name: title,
    url_en: enUrl,
    url_uk: ukMatch ? ukMatch['Address'] : ''
  });
}

return [{
  json: {
    canonicals,
    canonicals_count: data.pages_canonical_count,
    structure,
    domain: data.domain
  }
}];

// Agent 2: Meta Tags Analysis
const data = $('Parse XLSX').first().json;
const domain = data.domain;

// Use pre-filtered meta issues from Parse XLSX
const pages = data.pages_meta_issues || [];

const manualMeta = pages.map(p => ({
  url: p['Address'] || '',
  title_current: p['Title 1'] || '',
  title_len: parseInt(p['Title 1 Length'] || '0'),
  desc_current: p['Meta Description 1'] || '',
  desc_len: parseInt(p['Meta Description 1 Length'] || '0')
}));

return [{
  json: {
    manualMeta,
    manualMetaCount: manualMeta.length,
    domain
  }
}];

// Agent 3: H1 Problems
const data = $('Parse XLSX').first().json;

const multiH1 = (data.pages_multi_h1 || []).map(p => ({
  url: p['Address'] || '',
  h1_1: p['H1-1'] || '',
  h1_2: p['H1-2'] || '',
  h1_3: p['H1-3'] || ''
}));

const missingH1 = (data.pages_missing_h1 || []).map(p => ({
  url: p['Address'] || '',
  h1: ''
}));

return [{
  json: {
    multiH1,
    multiH1Count: data.pages_multi_h1_count,
    missingH1,
    missingH1Count: data.pages_missing_h1_count
  }
}];

// Agent 4: Redirects and Errors (301 + 404)
const data = $('Parse XLSX').first().json;

const pages301 = (data.pages_301 || []).map(p => ({
  address: p['Address'] || '',
  redirect_url: p['Redirect URL'] || p['Redirect URI'] || '',
  redirect_type: p['Redirect Type'] || 'Permanent',
  title: p['Title 1'] || '',
  status_code: '301'
}));

const pages404 = (data.pages_404 || []).map(p => ({
  address: p['Address'] || '',
  title: p['Title 1'] || '',
  crawl_depth: p['Crawl Depth'] || '',
  status_code: '404'
}));

return [{
  json: {
    pages301,
    pages301Count: data.pages_301_count,
    pages404,
    pages404Count: data.pages_404_count
  }
}];

// Agent 5: ALT Images
// This reads from optional images_alt files passed in the webhook
// If not provided, will parse from internal_all data
const input = $('Parse Input').first().json;
const data = $('Parse XLSX').first().json;

let altImages = [];

// If we have binary images_alt files, they would need separate parsing
// For now, extract from internal_all where Content Type contains 'image'
const allPages = data.pages_all_sample || [];

// Images without alt — look for image entries in the crawl data
// The Screaming Frog Images tab data comes from separate files
// Here we create placeholder for the sheet

return [{
  json: {
    altImages,
    altImagesCount: altImages.length,
    hasImagesAlt: input.hasImagesAlt
  }
}];

// Agent 6: Tag Pages
const data = $('Parse XLSX').first().json;
const domain = data.domain;

const enTags = (data.pages_tags || []).filter(p => !/\/uk\//.test(p['Address'] || ''));
const ukTags = (data.pages_tags || []).filter(p => /\/uk\//.test(p['Address'] || ''));

const tagPages = [];
for (const en of enTags) {
  const enUrl = en['Address'] || '';
  const h1 = en['H1-1'] || '';
  // Try to find UK equivalent
  const slug = enUrl.match(/\/tag\/([^/]+)/)?.[1] || '';
  const ukMatch = ukTags.find(uk => {
    const ukSlug = (uk['Address'] || '').match(/\/tag\/([^/]+)/)?.[1] || '';
    return ukSlug === slug || ukSlug === slug + '-uk';
  });
  tagPages.push({
    en_url: enUrl,
    uk_url: ukMatch ? ukMatch['Address'] : 'Потрібно додати',
    h1: h1
  });
}

return [{
  json: {
    tagPages,
    tagPagesCount: data.pages_tags_count,
    domain
  }
}];

// Agent 7: Status Tracker — aggregate all issues into task list
const canonicals = $('Agent 1: Canonicals + Structure').first().json;
const meta = $('Agent 2: Meta Tags').first().json;
const h1 = $('Agent 3: H1 Problems').first().json;
const redirects = $('Agent 4: Redirects & Errors').first().json;
const alt = $('Agent 5: ALT Images').first().json;
const tags = $('Agent 6: Tag Pages').first().json;

const tasks = [];
const today = new Date().toISOString().split('T')[0];

function addTask(name, priority, impact, count) {
  if (count > 0) {
    tasks.push({
      task: name,
      priority: priority,
      impact: impact,
      status: 'Потрібно виправити',
      date_set: today,
      deadline: '',
      assignee: '',
      date_check: '',
      date_done: '',
      comment_exec: '',
      comment_seo: `Знайдено ${count} проблем(и)`,
      count: count
    });
  }
}

addTask('Canonicals — некоректні canonical-теги', 5, 3, canonicals.canonicals_count);
addTask('Множественні H1', 4, 2, h1.multiH1Count);
addTask('Відсутні H1', 4, 3, h1.missingH1Count);
addTask('301 редиректи — внутрішні посилання', 4, 2, redirects.pages301Count);
addTask('404 помилки — биті посилання', 5, 3, redirects.pages404Count);
addTask('ALT-атрибути — зображення без alt', 3, 1, alt.altImagesCount);
addTask('Сторінки тегів — без UK-версії', 3, 2, tags.tagPagesCount);

// Meta tag issues
const metaIssues = meta.manualMetaCount || 0;
addTask('Мета-теги — потребують оптимізації', 4, 3, metaIssues);

return [{
  json: {
    tasks,
    summary: {
      total_tasks: tasks.length,
      critical: tasks.filter(t => t.priority >= 5).length,
      high: tasks.filter(t => t.priority === 4).length,
      medium: tasks.filter(t => t.priority === 3).length
    }
  }
}];

// Process robots.txt response
const response = $input.first();
let robotsLines = [];

try {
  const body = response.json.data || response.json.body || '';
  if (typeof body === 'string' && body.trim()) {
    robotsLines = body.split('\n').map(line => ({ line: line.trim() })).filter(l => l.line);
  }
} catch(e) {
  robotsLines = [{ line: 'robots.txt не знайдено' }];
}

if (robotsLines.length === 0) {
  robotsLines = [{ line: 'robots.txt не знайдено' }];
}

return [{ json: { robotsLines } }];

// Build all 16 sheets data from merged agent results
var inp = $input.first().json;
var canonicals = inp.canonicals || {};
var meta = inp.meta || {};
var h1 = inp.h1 || {};
var redirects = inp.redirects || {};
var alt = inp.alt || {};
var tags = inp.tags || {};
var status = inp.status || {};
var robots = inp.robots || {};
var domain = inp.domain || '';

var sheetNames = [
  'Статуси', 'Canonicals', 'Аркуш22', 'Структура наявна',
  'Шаблони мета-тегів', 'Ручні мета-теги', 'Декілька Н1', 'Відсутні Н1',
  'Robots.txt', '301 сторінки', '404 сторінки', 'ALT',
  'Посилання', 'Сторінки тегів', 'Структура рекомендована', 'Аналіз GMB'
];

var sheetsData = [];

// Helper: wrap sheet name for range
function rng(name) { return "'" + name + "'!A1"; }

// 1. Статуси
var tasks = status.tasks || [];
var statusRows = [['Задача', 'Пріоритет', 'Вплив на КРІ', 'Статус', 'Дата постановки', 'DL', 'Виконавець', 'Дата перевірки', 'Дата впровадження', 'Коментар виконавця', 'Коментар SEO']];
for (var i = 0; i < tasks.length; i++) {
  var t = tasks[i];
  statusRows.push([t.task||'', String(t.priority||''), String(t.impact||''), t.status||'', t.date_set||'', '', '', '', '', '', t.comment_seo||'']);
}
if (tasks.length === 0) statusRows.push(['Проблем не знайдено', '', '', 'OK', '', '', '', '', '', '', '']);
sheetsData.push({range: rng('Статуси'), values: statusRows});

// 2. Canonicals
var canList = canonicals.canonicals || [];
var canRows = [['URL', 'Canonical (поточний)', 'Correct canonical']];
for (var i = 0; i < canList.length; i++) {
  var c = canList[i];
  canRows.push([c.url||'', c.canonical||'', c.correct_canonical||'']);
}
if (canList.length === 0) canRows.push(['Дані відсутні або не знайдено проблем', '', '']);
sheetsData.push({range: rng('Canonicals'), values: canRows});

// 3. Аркуш22 (top canonical issues highlighted)
var arkRows = [['URL', 'Canonical зараз', 'Canonical коректний']];
var arkSlice = canList.slice(0, 20);
for (var i = 0; i < arkSlice.length; i++) {
  var c = arkSlice[i];
  arkRows.push([c.url||'', c.canonical||'', c.correct_canonical||'']);
}
if (arkSlice.length === 0) arkRows.push(['Проблем з canonical не знайдено', '', '']);
sheetsData.push({range: rng('Аркуш22'), values: arkRows});

// 4. Структура наявна
var struct = canonicals.structure || [];
var structRows = [['Назва сторінки', 'URL EN', 'URL UK']];
for (var i = 0; i < struct.length; i++) {
  var s = struct[i];
  structRows.push([s.name||'', s.url_en||'', s.url_uk||'']);
}
if (struct.length === 0) structRows.push(['Дані відсутні', '', '']);
sheetsData.push({range: rng('Структура наявна'), values: structRows});

// 5. Шаблони мета-тегів (MANUAL — headers + template rows)
sheetsData.push({range: rng('Шаблони мета-тегів'), values: [
  ['Тип сторінки', 'Title шаблон', 'Description шаблон', 'Title приклад', 'Description приклад'],
  ['Головна сторінка', '', '', '', ''],
  ['Послуги / Категорії', '', '', '', ''],
  ['Блог / Статті', '', '', '', ''],
  ['Автори', '', '', '', ''],
  ['Контакти', '', '', '', ''],
  ['Теги', '', '', '', ''],
  ['Пагінація', '', '', '', ''],
  ['Інше', '', '', '', '']
]});

// 6. Ручні мета-теги (AUTO from Agent 2)
var manualMeta = meta.manualMeta || [];
var metaRows = [['URL', 'Title', 'Title LEN', 'Description', 'Description LEN']];
for (var i = 0; i < manualMeta.length; i++) {
  var m = manualMeta[i];
  metaRows.push([m.url||'', m.title_current||'', String(m.title_len||0), m.desc_current||'', String(m.desc_len||0)]);
}
if (manualMeta.length === 0) metaRows.push(['Дані відсутні або не знайдено проблем', '', '', '', '']);
sheetsData.push({range: rng('Ручні мета-теги'), values: metaRows});

// 7. Декілька Н1
var multiH1 = h1.multiH1 || [];
var mh1Rows = [['URL', 'H1-1', 'H1-2', 'H1-3']];
for (var i = 0; i < multiH1.length; i++) {
  var m = multiH1[i];
  mh1Rows.push([m.url||'', m.h1_1||'', m.h1_2||'', m.h1_3||'']);
}
if (multiH1.length === 0) mh1Rows.push(['Дані відсутні або не знайдено проблем', '', '', '']);
sheetsData.push({range: rng('Декілька Н1'), values: mh1Rows});

// 8. Відсутні Н1
var missingH1 = h1.missingH1 || [];
var missRows = [['URL', 'H1 заголовок']];
for (var i = 0; i < missingH1.length; i++) {
  missRows.push([missingH1[i].url||'', missingH1[i].h1||'']);
}
if (missingH1.length === 0) missRows.push(['Дані відсутні або не знайдено проблем', '']);
sheetsData.push({range: rng('Відсутні Н1'), values: missRows});

// 9. Robots.txt
var robotsLines = robots.robotsLines || [];
var robotsRows = [];
for (var i = 0; i < robotsLines.length; i++) {
  robotsRows.push([robotsLines[i].line || robotsLines[i] || '']);
}
if (robotsRows.length === 0) robotsRows.push(['robots.txt не знайдено']);
sheetsData.push({range: rng('Robots.txt'), values: robotsRows});

// Link columns header
var linkHeaders = ['Type', 'From', 'To', 'Anchor Text', 'Alt Text', 'Follow', 'Target', 'Rel', 'Status Code', 'Status', 'Path Type', 'Link Path', 'Link Position', 'Link Origin'];

// 10. 301 сторінки
var p301 = redirects.pages301 || [];
var r301 = [linkHeaders.slice(0, 3)]; // Simplified: Type, From (Address), To (Redirect URL)
r301[0] = ['Address', 'Status Code', 'Redirect URL', 'Redirect Type'];
for (var i = 0; i < p301.length; i++) {
  var p = p301[i];
  r301.push([p.address||p.from||'', '301', p.redirect_url||p.to||'', p.redirect_type||'']);
}
if (p301.length === 0) r301.push(['Дані відсутні або не знайдено проблем', '', '', '']);
sheetsData.push({range: rng('301 сторінки'), values: r301});

// 11. 404 сторінки
var p404 = redirects.pages404 || [];
var r404 = [['Address', 'Status Code', 'Title', 'Crawl Depth']];
for (var i = 0; i < p404.length; i++) {
  var p = p404[i];
  r404.push([p.address||p.from||'', '404', p.title||'', String(p.crawl_depth||'')]);
}
if (p404.length === 0) r404.push(['Дані відсутні або не знайдено проблем', '', '', '']);
sheetsData.push({range: rng('404 сторінки'), values: r404});

// 12. ALT (placeholder — needs separate images_alt file)
sheetsData.push({range: rng('ALT'), values: [
  ['Address', 'Alt Text', 'Image URL'],
  ['Потрібен окремий файл images_missing_alt з Screaming Frog', '', '']
]});

// 13. Посилання (MANUAL — Ahrefs data)
sheetsData.push({range: rng('Посилання'), values: [
  ['Referring page title', 'Referring page URL', 'HTTP code', 'Domain rating', 'UR', 'Domain traffic', 'Referring domains', 'Linked domains', 'External links', 'Page traffic', 'Keywords', 'Target URL', 'Anchor', 'Type', 'Content', 'Nofollow', 'UGC', 'Sponsored', 'Rendered', 'Raw', 'Discovered status']
]});

// 14. Сторінки тегів
var tagList = tags.tagPages || [];
var tagRows = [['EN сторінка', 'UK сторінка', 'Н1']];
for (var i = 0; i < tagList.length; i++) {
  var tg = tagList[i];
  tagRows.push([tg.en_url||'', tg.uk_url||'', tg.h1||'']);
}
if (tagList.length === 0) tagRows.push(['Дані відсутні або не знайдено тегів', '', '']);
sheetsData.push({range: rng('Сторінки тегів'), values: tagRows});

// 15. Структура рекомендована (MANUAL)
sheetsData.push({range: rng('Структура рекомендована'), values: [
  ['1 рівень вкладеності', '2 рівень вкладеності', '3 рівень вкладеності', '4 рівень вкладеності', 'Наявність сторінки']
]});

// 16. Аналіз GMB (MANUAL)
sheetsData.push({range: rng('Аналіз GMB'), values: [
  ['Категорія', 'Як у нас зараз', 'Що треба додати / змінити / перевірити', 'Навіщо це потрібно', 'Приклади']
]});

return [{
  json: {
    sheetTitle: 'Додаток до аудиту - ' + domain,
    sheetNames: sheetNames,
    sheetsData: sheetsData,
    domain: domain,
    tasks_count: tasks.length,
    summary: status.summary || {}
  }
}];

// Merge all agent results into a single object for Excel builder
const canonicals = $('Agent 1: Canonicals + Structure').first().json;
const meta = $('Agent 2: Meta Tags').first().json;
const h1 = $('Agent 3: H1 Problems').first().json;
const redirects = $('Agent 4: Redirects & Errors').first().json;
const alt = $('Agent 5: ALT Images').first().json;
const tags = $('Agent 6: Tag Pages').first().json;
const status = $('Agent 7: Status Tracker').first().json;
const robots = $('Parse robots.txt').first().json;
const input = $('Parse XLSX').first().json;

return [{
  json: {
    domain: input.domain,
    canonicals,
    meta,
    h1,
    redirects,
    alt,
    tags,
    status,
    robots,
    structure: canonicals  // Structure data is in canonicals agent
  }
}];

// Prepare AI analysis prompt from all agent data
const input = $('Parse XLSX').first().json;
const status = $('Agent 7: Status Tracker').first().json;
const canonicals = $('Agent 1: Canonicals + Structure').first().json;
const h1 = $('Agent 3: H1 Problems').first().json;
const redirects = $('Agent 4: Redirects & Errors').first().json;
const tags = $('Agent 6: Tag Pages').first().json;
const meta = $('Agent 2: Meta Tags').first().json;

const domain = input.domain;
const summary = {
  total_pages: input.total_pages,
  total_indexable: input.total_indexable,
  canonical_issues: canonicals.canonicals_count,
  multi_h1: h1.multiH1Count,
  missing_h1: h1.missingH1Count,
  redirects_301: redirects.pages301Count,
  errors_404: redirects.pages404Count,
  tag_pages: tags.tagPagesCount,
  meta_issues: meta.manualMetaCount,
  tasks: status.tasks
};

const taskLines = summary.tasks.map(function(t) {
  return '- [Пріоритет ' + t.priority + '] ' + t.task + ': ' + t.comment_seo;
}).join('\n');

const prompt = 'Ти — SEO-експерт. Проаналізуй результати технічного аудиту сайту ' + domain + '.\n\n' +
  'Дані аудиту:\n' +
  '- Всього сторінок проскановано: ' + summary.total_pages + '\n' +
  '- Індексованих сторінок: ' + summary.total_indexable + '\n' +
  '- Некоректних canonical: ' + summary.canonical_issues + '\n' +
  '- Сторінок з кількома H1: ' + summary.multi_h1 + '\n' +
  '- Сторінок без H1: ' + summary.missing_h1 + '\n' +
  '- 301 редиректів: ' + summary.redirects_301 + '\n' +
  '- 404 помилок: ' + summary.errors_404 + '\n' +
  '- Сторінок тегів: ' + summary.tag_pages + '\n' +
  '- Проблем з мета-тегами: ' + summary.meta_issues + '\n\n' +
  'Задачі з пріоритетами:\n' + taskLines + '\n\n' +
  'Створи структурований звіт українською мовою з такими розділами:\n' +
  '1. Загальне резюме аудиту\n' +
  '2. Аналіз canonical-тегів\n' +
  '3. Аналіз структури сайту (EN/UK)\n' +
  '4. Аналіз мета-тегів (Title, Description)\n' +
  '5. Аналіз заголовків H1\n' +
  '6. Аналіз редиректів (301) та битих посилань (404)\n' +
  '7. Аналіз зображень (ALT)\n' +
  '8. Аналіз сторінок тегів\n' +
  '9. Аналіз robots.txt\n' +
  '10. Пріоритезований список задач\n' +
  '11. Висновки та рекомендації\n\n' +
  'Для кожного розділу вкажи:\n' +
  '- Кількість знайдених проблем\n' +
  '- Конкретні приклади URL (2-3)\n' +
  '- Рекомендації щодо виправлення\n' +
  '- Оцінку критичності (Критично / Високо / Середньо / Низько)';

return [{ json: { prompt, domain, summary } }];

// Prepare document title and content for Google Docs API
const domain = $('Parse XLSX').first().json.domain;
const dateToday = new Date().toISOString().split('T')[0];
const aiContent = $json.message?.content || $json.content || $json.text || 'Звіт генерується...';

return [{
  json: {
    docTitle: `SEO Тех. аудит — ${domain} — ${dateToday}`,
    docContent: aiContent
  }
}];

// Final response — send back Sheet URL and Doc URL
const domain = $('Parse XLSX').first().json.domain;

// Get spreadsheet ID from Create Google Sheet node
let excelId = '';
try {
  excelId = $('Create Google Sheet').first().json.spreadsheetId || '';
} catch(e) {}

// Get doc ID from Create Google Doc node
let docId = '';
try {
  docId = $('Create Google Doc').first().json.documentId || '';
} catch(e) {}

const excelUrl = excelId ? 'https://docs.google.com/spreadsheets/d/' + excelId : '';
const docUrl = docId ? 'https://docs.google.com/document/d/' + docId : '';

return [{
  json: {
    status: 'completed',
    message: 'Тех. аудит ' + domain + ' завершено',
    excelUrl: excelUrl,
    docUrl: docUrl,
    folderUrl: '',
    domain: domain
  }
}];

// Combine spreadsheetId from Google response + sheetsData from Build Excel
const spreadsheetId = $json.spreadsheetId;
const sheetsData = $('Build Excel').first().json.sheetsData;

return [{
  json: {
    spreadsheetId,
    batchBody: {
      valueInputOption: "RAW",
      data: sheetsData
    }
  }
}];
